import AppKit
import ApplicationServices
import Carbon
import CoreGraphics

extension PasteTyper {
    /// NSPasteboard.general, or another pasteboard (tests use one of their own).
    public final class SystemPasteboard: Pasteboard {
        /// Written with the text, so clipboard managers leave it out (nspasteboard.org): it's only there for a moment,
        /// it may be private, and it wasn't copied by you.
        static let markers = [
            "org.nspasteboard.TransientType", "org.nspasteboard.ConcealedType", "org.nspasteboard.AutoGeneratedType",
        ]

        private let pasteboard: NSPasteboard

        public init(_ pasteboard: NSPasteboard = .general) {
            self.pasteboard = pasteboard
        }

        public var changeCount: Int { pasteboard.changeCount }

        /// NSPasteboard.accessBehavior from macOS 15.4; a behaviour macOS adds later counts as asking each time.
        public var access: PasteboardAccess {
            guard #available(macOS 15.4, *) else { return .unrestricted }
            switch pasteboard.accessBehavior {
            case .default: return .default
            case .ask: return .ask
            case .alwaysAllow: return .alwaysAllow
            case .alwaysDeny: return .alwaysDeny
            @unknown default: return .ask
            }
        }

        /// Every item, each with every type whose data can be read; a type that can't (a promise its app no longer
        /// keeps) is skipped, as on Windows. When nothing can be read, or nothing but empty data (as a refusal might
        /// read), the pasteboard is unreadable, never empty: it isn't emptied or overwritten afterwards.
        public func save() -> Saved {
            guard let types = pasteboard.types, !types.isEmpty else { return .empty }
            var items: [[Contents.Representation]] = []
            for item in pasteboard.pasteboardItems ?? [] {
                let representations = item.types.compactMap { type in
                    item.data(forType: type).map { Contents.Representation(type: type.rawValue, data: $0) }
                }

                if !representations.isEmpty {
                    items.append(representations)
                }
            }

            let readable = items.joined().contains { !$0.data.isEmpty }
            return readable ? .items(Contents(items: items)) : .unreadable
        }

        /// The text and the markers, for this Mac only: Universal Clipboard doesn't offer it to your other devices (as
        /// Windows keeps it from the cloud clipboard).
        public func write(_ text: String) throws -> Int {
            _ = pasteboard.prepareForNewContents(with: .currentHostOnly)
            let item = NSPasteboardItem()
            _ = item.setString(text, forType: .string)
            for marker in Self.markers {
                _ = item.setData(Data(), forType: NSPasteboard.PasteboardType(marker))
            }

            guard pasteboard.writeObjects([item]) else { throw Failure.pasteboardUnavailable }
            return pasteboard.changeCount
        }

        public func restore(_ saved: Saved) {
            switch saved {
            case .unreadable:
                return
            case .empty:
                _ = pasteboard.prepareForNewContents(with: [])
            case .items(let contents):
                _ = pasteboard.prepareForNewContents(with: contents.isConcealed ? .currentHostOnly : [])
                let items = contents.items.map { representations in
                    let item = NSPasteboardItem()
                    for representation in representations {
                        let type = NSPasteboard.PasteboardType(representation.type)
                        _ = item.setData(representation.data, forType: type)
                    }

                    return item
                }

                _ = pasteboard.writeObjects(items)
            }
        }
    }

    /// The keyboard: the modifier keys held now, and keys sent with CGEvent, which needs the permission to post events
    /// (`Permissions.Kind.postEvents`). ⌘V is the key that types "v" with ⌘ in the keyboard layout in use (Dvorak's
    /// is QWERTY's "."), as Windows' Ctrl+V is the V key of the layout in use. Keys sent from ThumbFree carry its
    /// process identifier, so its own dictation key ignores them.
    public final class SystemKeys: NSObject, Keys, @unchecked Sendable {
        private let permissions: Permissions
        private let lock = NSLock()
        private var pasteKey = CGKeyCode(kVK_ANSI_V)

        public override convenience init() {
            self.init(permissions: Permissions())
        }

        /// Text Input Sources answers on the main thread only, so the paste key is found there, now or as soon as the
        /// main thread is free, and again whenever the keyboard layout changes.
        /// - Parameter permissions: Where the permission to post events is checked, before each key.
        public init(permissions: Permissions) {
            self.permissions = permissions
            super.init()
            if Thread.isMainThread {
                watchLayout()
            } else {
                DispatchQueue.main.async { [weak self] in self?.watchLayout() }
            }
        }

        deinit {
            DistributedNotificationCenter.default().removeObserver(self)
        }

        /// The keys held on the keyboard itself (the HID state): ThumbFree's own ⌘V doesn't count, so the next line
        /// doesn't wait for it.
        public var heldModifiers: Modifiers {
            let flags = CGEventSource.flagsState(.hidSystemState)
            var held: Modifiers = []
            if flags.contains(.maskCommand) { held.insert(.command) }
            if flags.contains(.maskAlternate) { held.insert(.option) }
            if flags.contains(.maskControl) { held.insert(.control) }
            if flags.contains(.maskShift) { held.insert(.shift) }
            if flags.contains(.maskSecondaryFn) { held.insert(.function) }
            return held
        }

        public var secureInput: FocusedField.SecureInput { FocusedField.SecureInput.current() }

        public var pasteChord: Chord {
            Chord(key: lock.withLock { pasteKey }, modifiers: .command)
        }

        /// Key down and up, with the chord's modifier flags only: nothing else held reaches the app (the typer waits
        /// for held keys to be let go first). Without the permission to post events macOS would drop them silently,
        /// so nothing goes out and `Failure.notAllowed` is thrown.
        public func post(_ chord: Chord) throws {
            try send(chord.key, flags: Self.eventFlags(chord.modifiers))
        }

        /// A key with `characters` as what it types (CGEventKeyboardSetUnicodeString) and no modifiers, so the
        /// keyboard layout doesn't matter. The key is the ANSI A key, as such typing usually is: apps take the
        /// characters.
        public func type(_ characters: String) throws {
            try send(0, flags: [], characters: Array(characters.utf16))
        }

        /// The modifiers' flags, each with the left-hand key's own bit too (NX_DEVICELCMDKEYMASK and so on), as a real
        /// key press has: some apps look at those.
        static func eventFlags(_ modifiers: Modifiers) -> CGEventFlags {
            var flags: UInt64 = 0
            if modifiers.contains(.command) { flags |= CGEventFlags.maskCommand.rawValue | 0x08 }
            if modifiers.contains(.option) { flags |= CGEventFlags.maskAlternate.rawValue | 0x20 }
            if modifiers.contains(.control) { flags |= CGEventFlags.maskControl.rawValue | 0x01 }
            if modifiers.contains(.shift) { flags |= CGEventFlags.maskShift.rawValue | 0x02 }
            if modifiers.contains(.function) { flags |= CGEventFlags.maskSecondaryFn.rawValue }
            return CGEventFlags(rawValue: flags)
        }

        /// Posts the key down and up that `events` makes, with the permission to post events only: without it macOS
        /// would drop them silently.
        private func send(_ key: CGKeyCode, flags: CGEventFlags, characters: [UniChar] = []) throws {
            guard permissions.status(.postEvents) == .granted else { throw Failure.notAllowed }
            guard let events = Self.events(key, flags: flags, characters: characters) else {
                throw Failure.keysUnavailable
            }

            events.down.post(tap: .cgSessionEventTap)
            events.up.post(tap: .cgSessionEventTap)
        }

        /// The key down and up for `key`, with `flags` as their only modifiers, carrying `characters`
        /// (CGEventKeyboardSetUnicodeString) when there are some, and marked as this process's
        /// (eventSourceUnixProcessID), which ThumbFree's own dictation key ignores. Making them needs no permission.
        static func events(_ key: CGKeyCode, flags: CGEventFlags, characters: [UniChar] = [])
            -> (down: CGEvent, up: CGEvent)?
        {
            let source = CGEventSource(stateID: .combinedSessionState)
            guard let down = CGEvent(keyboardEventSource: source, virtualKey: key, keyDown: true),
                  let up = CGEvent(keyboardEventSource: source, virtualKey: key, keyDown: false) else { return nil }
            let process = Int64(ProcessInfo.processInfo.processIdentifier)
            for event in [down, up] {
                if !characters.isEmpty {
                    event.keyboardSetUnicodeString(stringLength: characters.count, unicodeString: characters)
                }

                event.flags = flags
                event.setIntegerValueField(.eventSourceUnixProcessID, value: process)
            }

            return (down, up)
        }

        /// Finds the paste key now and whenever the keyboard layout changes. ThumbFree is almost never the active app,
        /// and the distributed center holds back notifications for inactive apps, so this one is delivered at once.
        private func watchLayout() {
            updatePasteKey()
            DistributedNotificationCenter.default().addObserver(
                self, selector: #selector(layoutChanged(_:)),
                name: Notification.Name(kTISNotifySelectedKeyboardInputSourceChanged as String), object: nil,
                suspensionBehavior: .deliverImmediately)
        }

        @objc private func layoutChanged(_ notification: Notification) {
            if Thread.isMainThread {
                updatePasteKey()
            } else {
                DispatchQueue.main.async { [weak self] in self?.updatePasteKey() }
            }
        }

        private func updatePasteKey() {
            let key = Self.keyCode(typing: "v") ?? CGKeyCode(kVK_ANSI_V)
            lock.withLock { pasteKey = key }
        }

        /// The key that types `character` with ⌘ held in the layout ⌘ shortcuts use: the current one, or for a
        /// non-Latin one (Russian, Greek…) the Latin layout that goes with it. Main thread only.
        static func keyCode(typing character: Character) -> CGKeyCode? {
            guard let source = TISCopyCurrentASCIICapableKeyboardLayoutInputSource()?.takeRetainedValue() else {
                return nil
            }

            return keyCode(typing: character, in: source)
        }

        /// The key that types `character` with ⌘ held in `layout` (with ⌘, "Dvorak – QWERTY ⌘" types QWERTY), found
        /// with UCKeyTranslate. Main thread only.
        static func keyCode(typing character: Character, in layout: TISInputSource) -> CGKeyCode? {
            guard character.utf16.count == 1, let unit = character.utf16.first,
                  let property = TISGetInputSourceProperty(layout, kTISPropertyUnicodeKeyLayoutData) else { return nil }
            let data = Unmanaged<CFData>.fromOpaque(property).takeUnretainedValue()
            guard let bytes = CFDataGetBytePtr(data) else { return nil }

            let command = UInt32((cmdKey >> 8) & 0xFF)
            let keyboard = UInt32(LMGetKbdType())
            let options = OptionBits(kUCKeyTranslateNoDeadKeysMask)
            return bytes.withMemoryRebound(to: UCKeyboardLayout.self, capacity: 1) { keys -> CGKeyCode? in
                for code in UInt16(0)..<128 {
                    var deadKeys: UInt32 = 0
                    var length = 0
                    var typed = [UniChar](repeating: 0, count: 4)
                    let status = UCKeyTranslate(
                        keys, code, UInt16(kUCKeyActionDown), command, keyboard, options, &deadKeys, typed.count,
                        &length, &typed)
                    if status == 0, length == 1, typed[0] == unit {
                        return CGKeyCode(code)
                    }
                }

                return nil
            }
        }
    }
}
